// HasWorkstream applies the HasEdge predicate on the "workstream" edge.
func HasWorkstream() predicate.WorkstreamHealthSnapshot {
	return predicate.WorkstreamHealthSnapshot(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, false, WorkstreamTable, WorkstreamColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasWorkstreamWith applies the HasEdge predicate on the "workstream" edge with a given conditions (other predicates).
func HasWorkstreamWith(preds ...predicate.Workstream) predicate.WorkstreamHealthSnapshot {
	return predicate.WorkstreamHealthSnapshot(func(s *sql.Selector) {
		step := newWorkstreamStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// HasLatestEvidence applies the HasEdge predicate on the "latest_evidence" edge.
func HasLatestEvidence() predicate.WorkstreamHealthSnapshot {
	return predicate.WorkstreamHealthSnapshot(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, false, LatestEvidenceTable, LatestEvidenceColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasLatestEvidenceWith applies the HasEdge predicate on the "latest_evidence" edge with a given conditions (other predicates).
func HasLatestEvidenceWith(preds ...predicate.Evidence) predicate.WorkstreamHealthSnapshot {
	return predicate.WorkstreamHealthSnapshot(func(s *sql.Selector) {
		step := newLatestEvidenceStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.WorkstreamHealthSnapshot) predicate.WorkstreamHealthSnapshot {
	return predicate.WorkstreamHealthSnapshot(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.WorkstreamHealthSnapshot) predicate.WorkstreamHealthSnapshot {
	return predicate.WorkstreamHealthSnapshot(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.WorkstreamHealthSnapshot) predicate.WorkstreamHealthSnapshot {
	return predicate.WorkstreamHealthSnapshot(sql.NotPredicates(p))
}
